tools.input:
W=<trial>; mkdir -p $W/work; cat > $W/work/a.tuft <<'E'
@h := find text "fn trial_blob(" at "9e0c8d648852e2e6f27c6f9517c71d8e5ea67a49" limit 100;
@e := retain @h around lines 0;
@v := project @e [path, line, excerpt(max_chars: 300)] sort [path asc, line asc];
emit @v budget_tokens 2000;
E
$W/../../bin/writfold tuft run $W/work/a.tuft --repo $W/repo --state $W/state
